/* Lei seca — dispositivos mais cobrados, com o texto literal da lei.
   Cada item: {id, m: matéria, ref: dispositivo, t: texto literal, l: [trecho da lacuna, errada, errada, errada], e: versão alterada (errada) para o certo/errado, ex: o que foi alterado}.
   Textos conferidos com as páginas oficiais do Planalto (legislação compilada). */
window.LEISECA=[
/* Constituição */
{id:"cf5xi",m:"const",ref:"Art. 5º, XI, da Constituição",t:"a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial;",l:["durante o dia","a qualquer hora","durante a noite","em horário comercial"],e:"a casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, a qualquer hora, por determinação judicial;",ex:"A ordem judicial só autoriza a entrada durante o dia. Flagrante, desastre e socorro autorizam a entrada a qualquer hora."},
{id:"cf5xii",m:"const",ref:"Art. 5º, XII, da Constituição",t:"é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual penal;",l:["investigação criminal ou instrução processual penal","qualquer processo judicial","investigação civil ou administrativa","defesa da ordem pública"],e:"é inviolável o sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, salvo, no último caso, por ordem judicial, nas hipóteses e na forma que a lei estabelecer para fins de investigação criminal ou instrução processual civil;",ex:"A interceptação telefônica só serve à investigação criminal ou à instrução processual penal, nunca a processo civil."},
{id:"cf5xvi",m:"const",ref:"Art. 5º, XVI, da Constituição",t:"todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo apenas exigido prévio aviso à autoridade competente;",l:["prévio aviso","prévia autorização","prévio pagamento de taxa","prévia licença judicial"],e:"todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, mediante prévia autorização da autoridade competente, desde que não frustrem outra reunião anteriormente convocada para o mesmo local;",ex:"A reunião não depende de autorização. Basta o prévio aviso à autoridade."},
{id:"cf5xxxv",m:"const",ref:"Art. 5º, XXXV, da Constituição",t:"a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito;",l:["lesão ou ameaça a direito","apenas lesão a direito","lesão a direito líquido e certo","ameaça a direito já reconhecido"],e:"a lei não excluirá da apreciação do Poder Judiciário lesão a direito;",ex:"A Constituição protege também contra a ameaça a direito, o que fundamenta a tutela preventiva."},
{id:"cf5xxxvi",m:"const",ref:"Art. 5º, XXXVI, da Constituição",t:"a lei não prejudicará o direito adquirido, o ato jurídico perfeito e a coisa julgada;",l:["o ato jurídico perfeito","a expectativa de direito","o negócio jurídico anulável","a decisão liminar"],e:"a lei não prejudicará o direito adquirido, a expectativa de direito e a coisa julgada;",ex:"A Constituição protege o ato jurídico perfeito. A mera expectativa de direito não é protegida."},
{id:"cf5xl",m:"const",ref:"Art. 5º, XL, da Constituição",t:"a lei penal não retroagirá, salvo para beneficiar o réu;",l:["para beneficiar o réu","nos crimes hediondos","por decisão do STF","nos crimes de menor potencial ofensivo"],e:"a lei penal não retroagirá, salvo nos crimes hediondos;",ex:"A única exceção à irretroatividade da lei penal é a lei mais benéfica ao réu."},
{id:"cf5xlii",m:"const",ref:"Art. 5º, XLII, da Constituição",t:"a prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão, nos termos da lei;",l:["inafiançável e imprescritível","afiançável e imprescritível","inafiançável e insuscetível de graça","imprescritível, mas afiançável"],e:"a prática do racismo constitui crime inafiançável e insuscetível de graça ou anistia, sujeito à pena de reclusão, nos termos da lei;",ex:"O racismo é inafiançável e imprescritível. Insuscetíveis de graça ou anistia são a tortura, o tráfico, o terrorismo e os hediondos (inciso XLIII)."},
{id:"cf5lvii",m:"const",ref:"Art. 5º, LVII, da Constituição",t:"ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória;",l:["trânsito em julgado","julgamento em segunda instância","recebimento da denúncia","sentença de primeiro grau"],e:"ninguém será considerado culpado até a confirmação da sentença penal condenatória em segunda instância;",ex:"A presunção de inocência vai até o trânsito em julgado (STF, ADCs 43, 44 e 54)."},
{id:"cf5lxi",m:"const",ref:"Art. 5º, LXI, da Constituição",t:"ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;",l:["autoridade judiciária competente","autoridade policial competente","autoridade judiciária ou policial","membro do Ministério Público"],e:"ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária ou policial competente, salvo nos casos de transgressão militar ou crime propriamente militar, definidos em lei;",ex:"Fora do flagrante, só a autoridade judiciária pode ordenar prisão. A autoridade policial não pode."},
{id:"cf5lxvii",m:"const",ref:"Art. 5º, LXVII, da Constituição",t:"não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento voluntário e inescusável de obrigação alimentícia e a do depositário infiel;",l:["voluntário e inescusável","involuntário","parcial","de qualquer natureza"],e:"não haverá prisão civil por dívida, salvo a do responsável pelo inadimplemento de qualquer obrigação alimentícia e a do depositário infiel;",ex:"O texto exige inadimplemento voluntário e inescusável. Atenção: pela Súmula Vinculante 25, a prisão do depositário infiel, embora no texto, é ilícita."},
{id:"cf5lxxviii",m:"const",ref:"Art. 5º, LXXVIII, da Constituição",t:"a todos, no âmbito judicial e administrativo, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação.",l:["no âmbito judicial e administrativo","apenas no âmbito judicial","no âmbito judicial e legislativo","apenas no processo penal"],e:"a todos, no âmbito judicial, são assegurados a razoável duração do processo e os meios que garantam a celeridade de sua tramitação.",ex:"A razoável duração vale também para o processo administrativo (EC 45/2004)."},
/* Estatuto da Advocacia */
{id:"oab6",m:"etica",ref:"Art. 6º, caput, do Estatuto da Advocacia (Lei 8.906/1994)",t:"Não há hierarquia nem subordinação entre advogados, magistrados e membros do Ministério Público, devendo todos tratar-se com consideração e respeito recíprocos.",l:["hierarquia nem subordinação","diferença de tratamento","dever de respeito","igualdade funcional"],e:"Não há hierarquia entre advogados, magistrados e membros do Ministério Público, mas o advogado deve obediência ao juiz da causa.",ex:"O Estatuto afasta tanto a hierarquia quanto a subordinação."},
{id:"oab25a",m:"etica",ref:"Art. 25-A do Estatuto da Advocacia (Lei 8.906/1994)",t:"Prescreve em cinco anos a ação de prestação de contas pelas quantias recebidas pelo advogado de seu cliente, ou de terceiros por conta dele (art. 34, XXI).",l:["cinco anos","três anos","dez anos","dois anos"],e:"Prescreve em três anos a ação de prestação de contas pelas quantias recebidas pelo advogado de seu cliente, ou de terceiros por conta dele (art. 34, XXI).",ex:"O prazo é de cinco anos."},
{id:"oab31",m:"etica",ref:"Art. 31, §1º, do Estatuto da Advocacia (Lei 8.906/1994)",t:"O advogado, no exercício da profissão, deve manter independência em qualquer circunstância.",l:["em qualquer circunstância","salvo perante o juiz","apenas perante o cliente","quando não for empregado"],e:"O advogado, no exercício da profissão, deve manter independência, salvo perante o empregador.",ex:"A independência deve ser mantida em qualquer circunstância, inclusive pelo advogado empregado (art. 18)."},
{id:"oab32",m:"etica",ref:"Art. 32 do Estatuto da Advocacia (Lei 8.906/1994)",t:"O advogado é responsável pelos atos que, no exercício profissional, praticar com dolo ou culpa.",l:["dolo ou culpa","dolo","culpa grave","qualquer resultado, independentemente de culpa"],e:"O advogado é responsável pelos atos que, no exercício profissional, praticar com dolo.",ex:"A responsabilidade do advogado é subjetiva e alcança o dolo e a culpa."},
{id:"oab43",m:"etica",ref:"Art. 43 do Estatuto da Advocacia (Lei 8.906/1994)",t:"A pretensão à punibilidade das infrações disciplinares prescreve em cinco anos, contados da data da constatação oficial do fato.",l:["da data da constatação oficial do fato","da data do fato","da instauração do processo","do trânsito em julgado da decisão"],e:"A pretensão à punibilidade das infrações disciplinares prescreve em cinco anos, contados da data em que o fato foi praticado.",ex:"O prazo conta da constatação oficial do fato, e não da data em que foi praticado."},
/* Código Penal */
{id:"cp1",m:"penal",ref:"Art. 1º do Código Penal",t:"Não há crime sem lei anterior que o defina. Não há pena sem prévia cominação legal.",l:["lei anterior","lei posterior","norma regulamentar","costume anterior"],e:"Não há crime sem lei ou medida provisória anterior que o defina. Não há pena sem prévia cominação legal.",ex:"A reserva legal exige lei em sentido estrito. Medida provisória não pode tratar de direito penal (art. 62, §1º, I, b, da Constituição)."},
{id:"cp2",m:"penal",ref:"Art. 2º, caput, do Código Penal",t:"Ninguém pode ser punido por fato que lei posterior deixa de considerar crime, cessando em virtude dela a execução e os efeitos penais da sentença condenatória.",l:["os efeitos penais","todos os efeitos, inclusive civis","apenas a execução da pena","os efeitos civis"],e:"Ninguém pode ser punido por fato que lei posterior deixa de considerar crime, cessando em virtude dela a execução e todos os efeitos, penais e civis, da sentença condenatória.",ex:"A abolitio criminis apaga os efeitos penais. Os efeitos civis, como o dever de indenizar, permanecem."},
{id:"cp4",m:"penal",ref:"Art. 4º do Código Penal",t:"Considera-se praticado o crime no momento da ação ou omissão, ainda que outro seja o momento do resultado.",l:["no momento da ação ou omissão","no momento do resultado","no momento da ação ou do resultado","no momento da descoberta do fato"],e:"Considera-se praticado o crime no momento do resultado, ainda que outro seja o momento da ação ou omissão.",ex:"Para o tempo do crime, o CP adota a teoria da atividade. Para o lugar (art. 6º), a da ubiquidade."},
{id:"cp6",m:"penal",ref:"Art. 6º do Código Penal",t:"Considera-se praticado o crime no lugar em que ocorreu a ação ou omissão, no todo ou em parte, bem como onde se produziu ou deveria produzir-se o resultado.",l:["bem como onde se produziu ou deveria produzir-se o resultado","excluído o lugar do resultado","apenas onde se produziu o resultado","apenas onde o agente tem domicílio"],e:"Considera-se praticado o crime no lugar em que ocorreu a ação ou omissão, no todo ou em parte, e não onde se produziu o resultado.",ex:"O lugar do crime segue a teoria da ubiquidade: tanto o da conduta quanto o do resultado."},
{id:"cp13",m:"penal",ref:"Art. 13, caput, do Código Penal",t:"O resultado, de que depende a existência do crime, somente é imputável a quem lhe deu causa. Considera-se causa a ação ou omissão sem a qual o resultado não teria ocorrido.",l:["sem a qual o resultado não teria ocorrido","que tenha sido a mais adequada para produzir o resultado","praticada com dolo","que tenha sido a última antes do resultado"],e:"O resultado, de que depende a existência do crime, somente é imputável a quem lhe deu causa. Considera-se causa apenas a ação ou omissão mais adequada a produzir o resultado.",ex:"O caput adota a teoria da equivalência dos antecedentes (conditio sine qua non)."},
{id:"cp15",m:"penal",ref:"Art. 15 do Código Penal",t:"O agente que, voluntariamente, desiste de prosseguir na execução ou impede que o resultado se produza, só responde pelos atos já praticados.",l:["voluntariamente","espontaneamente e por medo","por circunstâncias alheias à sua vontade","depois de consumado o crime"],e:"O agente que, voluntariamente, desiste de prosseguir na execução ou impede que o resultado se produza, responde pela tentativa, com pena reduzida.",ex:"Na desistência voluntária e no arrependimento eficaz, o agente só responde pelos atos já praticados, e não por tentativa."},
{id:"cp16",m:"penal",ref:"Art. 16 do Código Penal",t:"Nos crimes cometidos sem violência ou grave ameaça à pessoa, reparado o dano ou restituída a coisa, até o recebimento da denúncia ou da queixa, por ato voluntário do agente, a pena será reduzida de um a dois terços.",l:["até o recebimento da denúncia ou da queixa","até a sentença","até o oferecimento da denúncia","até o trânsito em julgado"],e:"Nos crimes cometidos sem violência ou grave ameaça à pessoa, reparado o dano ou restituída a coisa, até a sentença, por ato voluntário do agente, a pena será reduzida de um a dois terços.",ex:"O arrependimento posterior vai até o recebimento da denúncia ou queixa. Depois disso, a reparação é só atenuante (art. 65, III, b)."},
{id:"cp17",m:"penal",ref:"Art. 17 do Código Penal",t:"Não se pune a tentativa quando, por ineficácia absoluta do meio ou por absoluta impropriedade do objeto, é impossível consumar-se o crime.",l:["absoluta","relativa","absoluta ou relativa","qualquer"],e:"Não se pune a tentativa quando, por ineficácia absoluta ou relativa do meio ou por impropriedade do objeto, é impossível consumar-se o crime.",ex:"O crime impossível exige ineficácia absoluta do meio ou impropriedade absoluta do objeto. Se for relativa, há tentativa punível."},
{id:"cp21",m:"penal",ref:"Art. 21, caput, do Código Penal",t:"O desconhecimento da lei é inescusável. O erro sobre a ilicitude do fato, se inevitável, isenta de pena; se evitável, poderá diminuí-la de um sexto a um terço.",l:["isenta de pena","exclui o dolo","diminui a pena de um terço","exclui a tipicidade"],e:"O desconhecimento da lei é inescusável. O erro sobre a ilicitude do fato, se inevitável, exclui o dolo; se evitável, permite a punição por crime culposo.",ex:"O erro de proibição inevitável isenta de pena (exclui a culpabilidade). Excluir o dolo é efeito do erro de tipo (art. 20)."},
{id:"cp25",m:"penal",ref:"Art. 25, caput, do Código Penal",t:"Entende-se em legítima defesa quem, usando moderadamente dos meios necessários, repele injusta agressão, atual ou iminente, a direito seu ou de outrem.",l:["atual ou iminente","atual, iminente ou futura","apenas atual","passada ou atual"],e:"Entende-se em legítima defesa quem, usando moderadamente dos meios necessários, repele injusta agressão, atual, iminente ou futura, a direito seu ou de outrem.",ex:"A agressão deve ser atual ou iminente. Reação contra agressão futura ou já terminada não é legítima defesa."},
{id:"cp27",m:"penal",ref:"Art. 27 do Código Penal",t:"Os menores de dezoito anos são penalmente inimputáveis, ficando sujeitos às normas estabelecidas na legislação especial.",l:["dezoito","dezesseis","vinte e um","catorze"],e:"Os menores de dezesseis anos são penalmente inimputáveis, ficando sujeitos às normas estabelecidas na legislação especial.",ex:"A inimputabilidade vai até os 18 anos (critério biológico), também prevista no art. 228 da Constituição."},
/* Código Civil */
{id:"cc2",m:"civil",ref:"Art. 2º do Código Civil",t:"A personalidade civil da pessoa começa do nascimento com vida; mas a lei põe a salvo, desde a concepção, os direitos do nascituro.",l:["do nascimento com vida","da concepção","do registro civil","dos dezoito anos"],e:"A personalidade civil da pessoa começa da concepção, quando a lei põe a salvo os direitos do nascituro.",ex:"A personalidade começa do nascimento com vida. Desde a concepção, a lei apenas põe a salvo os direitos do nascituro."},
{id:"cc3",m:"civil",ref:"Art. 3º do Código Civil",t:"São absolutamente incapazes de exercer pessoalmente os atos da vida civil os menores de 16 (dezesseis) anos.",l:["os menores de 16 (dezesseis) anos","os menores de 18 (dezoito) anos","os que não puderem exprimir sua vontade","os pródigos"],e:"São absolutamente incapazes de exercer pessoalmente os atos da vida civil os menores de 16 (dezesseis) anos e os que, por enfermidade ou deficiência mental, não tiverem o necessário discernimento.",ex:"Desde o Estatuto da Pessoa com Deficiência (Lei 13.146/2015), só os menores de 16 anos são absolutamente incapazes."},
{id:"cc5",m:"civil",ref:"Art. 5º, caput, do Código Civil",t:"A menoridade cessa aos dezoito anos completos, quando a pessoa fica habilitada à prática de todos os atos da vida civil.",l:["dezoito anos completos","vinte e um anos completos","dezesseis anos completos","dezoito anos, com o registro"],e:"A menoridade cessa aos vinte e um anos completos, quando a pessoa fica habilitada à prática de todos os atos da vida civil.",ex:"A menoridade cessa aos dezoito anos. Vinte e um era a regra do Código de 1916."},
{id:"cc6",m:"civil",ref:"Art. 6º do Código Civil",t:"A existência da pessoa natural termina com a morte; presume-se esta, quanto aos ausentes, nos casos em que a lei autoriza a abertura de sucessão definitiva.",l:["sucessão definitiva","sucessão provisória","curadoria dos bens","declaração de ausência"],e:"A existência da pessoa natural termina com a morte; presume-se esta, quanto aos ausentes, a partir da declaração de ausência.",ex:"A morte do ausente é presumida quando a lei autoriza a abertura da sucessão definitiva, e não com a simples declaração de ausência."},
/* CDC */
{id:"cdc2",m:"cdc",ref:"Art. 2º, caput, do Código de Defesa do Consumidor (Lei 8.078/1990)",t:"Consumidor é toda pessoa física ou jurídica que adquire ou utiliza produto ou serviço como destinatário final.",l:["pessoa física ou jurídica","pessoa física","pessoa física ou microempresa","pessoa física hipossuficiente"],e:"Consumidor é toda pessoa física que adquire ou utiliza produto ou serviço como destinatário final.",ex:"A pessoa jurídica também pode ser consumidora, desde que seja destinatária final."},
{id:"cdc26",m:"cdc",ref:"Art. 26 do Código de Defesa do Consumidor (Lei 8.078/1990)",t:"O direito de reclamar pelos vícios aparentes ou de fácil constatação caduca em: I - trinta dias, tratando-se de fornecimento de serviço e de produtos não duráveis; II - noventa dias, tratando-se de fornecimento de serviço e de produtos duráveis.",l:["noventa dias","sessenta dias","cento e oitenta dias","um ano"],e:"O direito de reclamar pelos vícios aparentes ou de fácil constatação caduca em: I - sete dias, tratando-se de fornecimento de serviço e de produtos não duráveis; II - trinta dias, tratando-se de fornecimento de serviço e de produtos duráveis.",ex:"Os prazos são de trinta dias (não duráveis) e noventa dias (duráveis). Sete dias é o prazo de arrependimento (art. 49)."},
{id:"cdc27",m:"cdc",ref:"Art. 27 do Código de Defesa do Consumidor (Lei 8.078/1990)",t:"Prescreve em cinco anos a pretensão à reparação pelos danos causados por fato do produto ou do serviço prevista na Seção II deste Capítulo, iniciando-se a contagem do prazo a partir do conhecimento do dano e de sua autoria.",l:["a partir do conhecimento do dano e de sua autoria","a partir da compra do produto","a partir da ocorrência do dano","a partir da entrega do produto"],e:"Prescreve em cinco anos a pretensão à reparação pelos danos causados por fato do produto ou do serviço prevista na Seção II deste Capítulo, iniciando-se a contagem do prazo a partir da data da compra.",ex:"O prazo começa com o conhecimento do dano e de sua autoria."},
{id:"cdc42",m:"cdc",ref:"Art. 42, parágrafo único, do Código de Defesa do Consumidor (Lei 8.078/1990)",t:"O consumidor cobrado em quantia indevida tem direito à repetição do indébito, por valor igual ao dobro do que pagou em excesso, acrescido de correção monetária e juros legais, salvo hipótese de engano justificável.",l:["ao dobro do que pagou em excesso","ao triplo do que pagou em excesso","ao valor simples do que pagou","ao dobro do valor cobrado, ainda que não pago"],e:"O consumidor cobrado em quantia indevida tem direito à repetição do indébito, por valor igual ao dobro do que lhe foi cobrado, ainda que não tenha pago, acrescido de correção monetária e juros legais.",ex:"A repetição em dobro exige pagamento em excesso e é afastada no engano justificável."},
{id:"cdc49",m:"cdc",ref:"Art. 49, caput, do Código de Defesa do Consumidor (Lei 8.078/1990)",t:"O consumidor pode desistir do contrato, no prazo de 7 dias a contar de sua assinatura ou do ato de recebimento do produto ou serviço, sempre que a contratação de fornecimento de produtos e serviços ocorrer fora do estabelecimento comercial, especialmente por telefone ou a domicílio.",l:["fora do estabelecimento comercial","em qualquer estabelecimento","dentro do estabelecimento comercial","apenas pela internet"],e:"O consumidor pode desistir do contrato, no prazo de 7 dias a contar de sua assinatura ou do ato de recebimento do produto ou serviço, em qualquer contratação, inclusive na loja física.",ex:"O direito de arrependimento vale só para compras fora do estabelecimento comercial."},
/* CTN */
{id:"ctn3",m:"trib",ref:"Art. 3º do Código Tributário Nacional",t:"Tributo é toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada.",l:["não constitua sanção de ato ilícito","constitua sanção de ato ilícito","possa ser paga em serviços","seja instituída por decreto"],e:"Tributo é toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa discricionária.",ex:"A cobrança do tributo é atividade plenamente vinculada, e não discricionária."},
{id:"ctn7",m:"trib",ref:"Art. 7º, caput, do Código Tributário Nacional",t:"A competência tributária é indelegável, salvo atribuição das funções de arrecadar ou fiscalizar tributos, ou de executar leis, serviços, atos ou decisões administrativas em matéria tributária, conferida por uma pessoa jurídica de direito público a outra, nos termos do § 3º do art. 18 da Constituição.",l:["indelegável","delegável por lei complementar","delegável a pessoas jurídicas de direito privado","delegável apenas da União aos Estados"],e:"A competência tributária é delegável por lei, inclusive a pessoas jurídicas de direito privado, que poderão instituir, arrecadar e fiscalizar tributos.",ex:"A competência para instituir tributo é indelegável. Só as funções de arrecadar e fiscalizar podem ser atribuídas, e apenas a pessoa jurídica de direito público."},
{id:"ctn123",m:"trib",ref:"Art. 123 do Código Tributário Nacional",t:"Salvo disposições de lei em contrário, as convenções particulares, relativas à responsabilidade pelo pagamento de tributos, não podem ser opostas à Fazenda Pública, para modificar a definição legal do sujeito passivo das obrigações tributárias correspondentes.",l:["não podem ser opostas à Fazenda Pública","podem ser opostas à Fazenda Pública","vinculam a Fazenda Pública se registradas em cartório","prevalecem sobre a lei tributária"],e:"Salvo disposições de lei em contrário, as convenções particulares, relativas à responsabilidade pelo pagamento de tributos, podem ser opostas à Fazenda Pública, desde que registradas em cartório.",ex:"Contratos entre particulares, como a cláusula que põe o IPTU a cargo do inquilino, não mudam o sujeito passivo perante o Fisco."},
{id:"ctn136",m:"trib",ref:"Art. 136 do Código Tributário Nacional",t:"Salvo disposição de lei em contrário, a responsabilidade por infrações da legislação tributária independe da intenção do agente ou do responsável e da efetividade, natureza e extensão dos efeitos do ato.",l:["independe da intenção do agente","depende da prova de dolo","depende da prova de culpa","depende do prejuízo ao Fisco"],e:"Salvo disposição de lei em contrário, a responsabilidade por infrações da legislação tributária depende da prova da intenção do agente ou do responsável.",ex:"Em regra, a responsabilidade por infrações tributárias é objetiva: independe da intenção."},
/* CLT e Constituição — Direito do Trabalho */
{id:"clt29",m:"trab",ref:"Art. 29, caput, da CLT",t:"O empregador terá o prazo de 5 (cinco) dias úteis para anotar na CTPS, em relação aos trabalhadores que admitir, a data de admissão, a remuneração e as condições especiais, se houver, facultada a adoção de sistema manual, mecânico ou eletrônico, conforme instruções a serem expedidas pelo Ministério da Economia.",l:["5 (cinco) dias úteis","48 (quarenta e oito) horas","10 (dez) dias corridos","30 (trinta) dias"],e:"O empregador terá o prazo de 48 (quarenta e oito) horas para anotar na CTPS, em relação aos trabalhadores que admitir, a data de admissão, a remuneração e as condições especiais, se houver, facultada a adoção de sistema manual, mecânico ou eletrônico, conforme instruções a serem expedidas pelo Ministério da Economia.",ex:"Desde a Lei 13.874/2019, o prazo é de 5 dias úteis. As 48 horas eram da redação antiga."},
{id:"cf7xiii",m:"trab",ref:"Art. 7º, XIII, da Constituição (redação da EC 141/2026)",t:"duração do trabalho normal não superior a 8 (oito) horas diárias e 40 (quarenta) horas semanais, facultada a compensação de horários e a redução da jornada, mediante acordo ou convenção coletiva de trabalho;",l:["40 (quarenta) horas semanais","44 (quarenta e quatro) horas semanais","36 (trinta e seis) horas semanais","48 (quarenta e oito) horas semanais"],e:"duração do trabalho normal não superior a 8 (oito) horas diárias e 44 (quarenta e quatro) horas semanais, facultada a compensação de horários e a redução da jornada, mediante acordo ou convenção coletiva de trabalho;",ex:"A EC 141/2026 reduziu o limite para 40 horas semanais, com transição (42 horas dois meses após a publicação e 40 horas um ano depois). As 44 horas eram a redação anterior."},
{id:"clt474",m:"trab",ref:"Art. 474 da CLT",t:"A suspensão do empregado por mais de 30 (trinta) dias consecutivos importa na rescisão injusta do contrato de trabalho.",l:["30 (trinta) dias consecutivos","15 (quinze) dias consecutivos","60 (sessenta) dias alternados","90 (noventa) dias consecutivos"],e:"A suspensão do empregado por mais de 30 (trinta) dias consecutivos importa na justa causa do empregado.",ex:"A suspensão disciplinar acima de 30 dias consecutivos gera rescisão injusta, e não justa causa do empregado."},
{id:"clt468",m:"trab",ref:"Art. 468, caput, da CLT",t:"Nos contratos individuais de trabalho só é lícita a alteração das respectivas condições por mútuo consentimento, e ainda assim desde que não resultem, direta ou indiretamente, prejuízos ao empregado, sob pena de nulidade da cláusula infringente desta garantia.",l:["por mútuo consentimento","por decisão do empregador","por acordo verbal","por decisão do sindicato"],e:"Nos contratos individuais de trabalho só é lícita a alteração das respectivas condições por mútuo consentimento, ainda que resultem prejuízos ao empregado.",ex:"A alteração exige mútuo consentimento e, além disso, ausência de prejuízo ao empregado."}
,{id:"cp121b",m:"penal",ref:"Art. 121-B do Código Penal (Lei 15.384/2026)",t:"Matar descendente, ascendente, dependente, enteado ou pessoa sob guarda ou responsabilidade direta da mulher, com o fim específico de causar-lhe sofrimento, punição ou controle, no contexto de violência doméstica e familiar. Pena – reclusão, de 20 (vinte) a 40 (quarenta) anos.",l:["20 (vinte) a 40 (quarenta) anos","12 (doze) a 30 (trinta) anos","6 (seis) a 20 (vinte) anos","8 (oito) a 15 (quinze) anos"],e:"Matar descendente, ascendente, dependente, enteado ou pessoa sob guarda ou responsabilidade direta da mulher, com o fim específico de causar-lhe sofrimento, punição ou controle, no contexto de violência doméstica e familiar. Pena – reclusão, de 12 (doze) a 30 (trinta) anos.",ex:"O vicaricídio tem a mesma pena do feminicídio: reclusão de 20 a 40 anos."}
,{id:"cp217a",m:"penal",ref:"Art. 217-A, caput e §4º-A, do Código Penal",t:"Ter conjunção carnal ou praticar outro ato libidinoso com menor de 14 (catorze) anos: Pena – reclusão, de 10 (dez) a 18 (dezoito) anos, e multa. (...) É absoluta a presunção de vulnerabilidade da vítima e inadmissível sua relativização.",l:["absoluta","relativa","afastada pelo consentimento","dependente de prova"],e:"Ter conjunção carnal ou praticar outro ato libidinoso com menor de 14 (catorze) anos: Pena – reclusão, de 10 (dez) a 18 (dezoito) anos, e multa. (...) É relativa a presunção de vulnerabilidade da vítima, podendo ser afastada no caso concreto.",ex:"Desde a Lei 15.353/2026, o §4º-A diz que a presunção é absoluta e inadmissível sua relativização."}
,{id:"lmp16a",m:"penal",ref:"Art. 16-A da Lei 11.340/2006 (Lei 15.438/2026)",t:"Nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, a ofendida decai do direito de queixa ou de representação se não o exerce no prazo de 12 (doze) meses, contado do dia em que veio a saber quem é o autor do crime.",l:["12 (doze) meses","6 (seis) meses","2 (dois) anos","30 (trinta) dias"],e:"Nos crimes praticados no âmbito de violência doméstica e familiar contra a mulher, a ofendida decai do direito de queixa ou de representação se não o exerce no prazo de 6 (seis) meses, contado do dia em que veio a saber quem é o autor do crime.",ex:"Na violência doméstica contra a mulher, o prazo de decadência é de 12 meses; a regra geral de 6 meses fica para os demais crimes."}
,{id:"cp136",m:"penal",ref:"Art. 136, caput, do Código Penal (Lei 15.163/2025)",t:"Expor a perigo a vida ou a saúde de pessoa sob sua autoridade, guarda ou vigilância, para fim de educação, ensino, tratamento ou custódia, quer privando-a de alimentação ou cuidados indispensáveis, quer sujeitando-a a trabalho excessivo ou inadequado, quer abusando de meios de correção ou disciplina: Pena - reclusão, de 2 (dois) a 5 (cinco) anos.",l:["reclusão, de 2 (dois) a 5 (cinco) anos","detenção, de 2 (dois) meses a 1 (um) ano, ou multa","detenção, de 6 (seis) meses a 3 (três) anos","reclusão, de 1 (um) a 4 (quatro) anos"],e:"Expor a perigo a vida ou a saúde de pessoa sob sua autoridade, guarda ou vigilância, para fim de educação, ensino, tratamento ou custódia, quer privando-a de alimentação ou cuidados indispensáveis, quer sujeitando-a a trabalho excessivo ou inadequado, quer abusando de meios de correção ou disciplina: Pena - detenção, de 2 (dois) meses a 1 (um) ano, ou multa.",ex:"A pena de detenção de 2 meses a 1 ano foi substituída, em 2025, por reclusão de 2 a 5 anos."}
/* Processo Civil, Processo Penal, Administrativo, Ambiental, Previdenciário, Eleitoral, Financeiro, ECA, Processo do Trabalho e Empresarial.
   Textos conferidos com a compilação atualizada do Congresso Nacional (normas.leg.br), em outubro de 2026. */
,{id:"cpc5",m:"pc",ref:"Art. 5º do CPC",t:"Aquele que de qualquer forma participa do processo deve comportar-se de acordo com a boa-fé.",l:["boa-fé", "verdade real", "vontade das partes", "orientação do juiz"],e:"Aquele que de qualquer forma participa do processo deve comportar-se de acordo com a verdade real.",ex:"É a boa-fé objetiva: vale para partes, advogados, juiz, MP e auxiliares. Quem a viola pode responder por litigância de má-fé (art. 80)."}
,{id:"cpc6",m:"pc",ref:"Art. 6º do CPC",t:"Todos os sujeitos do processo devem cooperar entre si para que se obtenha, em tempo razoável, decisão de mérito justa e efetiva.",l:["cooperar entre si", "obedecer ao juiz", "manter sigilo", "evitar recursos"],e:"Todos os sujeitos do processo devem obedecer ao juiz para que se obtenha, em tempo razoável, decisão de mérito justa e efetiva.",ex:"O princípio da cooperação inclui o juiz: ele deve esclarecer, consultar as partes e prevenir vícios (veja também o art. 10, que proíbe a decisão surpresa)."}
,{id:"cpc190",m:"pc",ref:"Art. 190, caput, do CPC",t:"Versando o processo sobre direitos que admitam autocomposição, é lícito às partes plenamente capazes estipular mudanças no procedimento para ajustá-lo às especificidades da causa e convencionar sobre os seus ônus, poderes, faculdades e deveres processuais, antes ou durante o processo.",l:["plenamente capazes", "maiores de 16 anos", "assistidas por advogado", "relativamente capazes"],e:"Versando o processo sobre direitos que admitam autocomposição, é lícito às partes maiores de 16 anos estipular mudanças no procedimento para ajustá-lo às especificidades da causa e convencionar sobre os seus ônus, poderes, faculdades e deveres processuais, antes ou durante o processo.",ex:"São os negócios jurídicos processuais atípicos. O juiz só recusa a convenção se houver nulidade, abuso em contrato de adesão ou parte em manifesta vulnerabilidade."}
,{id:"cpc219",m:"pc",ref:"Art. 219, caput, do CPC",t:"Na contagem de prazo em dias, estabelecido por lei ou pelo juiz, computar-se-ão somente os dias úteis.",l:["somente os dias úteis", "todos os dias corridos", "os dias úteis e os sábados", "os dias corridos, salvo feriados"],e:"Na contagem de prazo em dias, estabelecido por lei ou pelo juiz, computar-se-ão todos os dias corridos.",ex:"A regra vale só para prazos processuais (parágrafo único). Prazos de direito material, como a decadência, correm em dias corridos."}
,{id:"cpc300",m:"pc",ref:"Art. 300, caput, do CPC",t:"A tutela de urgência será concedida quando houver elementos que evidenciem a probabilidade do direito e o perigo de dano ou o risco ao resultado útil do processo.",l:["probabilidade do direito", "certeza do direito", "prova inequívoca do direito", "verossimilhança da alegação"],e:"A tutela de urgência será concedida quando houver elementos que evidenciem a certeza do direito e o perigo de dano ou o risco ao resultado útil do processo.",ex:"O CPC de 2015 trocou a 'prova inequívoca' e a 'verossimilhança' do código antigo pela probabilidade do direito, somada ao perigo da demora."}
,{id:"cpc334",m:"pc",ref:"Art. 334, caput, do CPC",t:"Se a petição inicial preencher os requisitos essenciais e não for o caso de improcedência liminar do pedido, o juiz designará audiência de conciliação ou de mediação com antecedência mínima de 30 (trinta) dias, devendo ser citado o réu com pelo menos 20 (vinte) dias de antecedência.",l:["30 (trinta) dias", "15 (quinze) dias", "20 (vinte) dias", "10 (dez) dias"],e:"Se a petição inicial preencher os requisitos essenciais e não for o caso de improcedência liminar do pedido, o juiz designará audiência de conciliação ou de mediação com antecedência mínima de 15 (quinze) dias, devendo ser citado o réu com pelo menos 20 (vinte) dias de antecedência.",ex:"Dois números diferentes: a audiência é marcada com 30 dias de antecedência, e o réu é citado com pelo menos 20 dias."}
,{id:"cpc344",m:"pc",ref:"Art. 344 do CPC",t:"Se o réu não contestar a ação, será considerado revel e presumir-se-ão verdadeiras as alegações de fato formuladas pelo autor.",l:["alegações de fato", "alegações de direito", "alegações de fato e de direito", "provas documentais"],e:"Se o réu não contestar a ação, será considerado revel e presumir-se-ão verdadeiras as alegações de direito formuladas pelo autor.",ex:"A presunção alcança só os fatos, nunca o direito, e é afastada nas hipóteses do art. 345 (por exemplo, direitos indisponíveis)."}
,{id:"cpc1003",m:"pc",ref:"Art. 1.003, §5º, do CPC",t:"Excetuados os embargos de declaração, o prazo para interpor os recursos e para responder-lhes é de 15 (quinze) dias.",l:["15 (quinze) dias", "5 (cinco) dias", "10 (dez) dias", "30 (trinta) dias"],e:"Excetuados os embargos de declaração, o prazo para interpor os recursos e para responder-lhes é de 5 (cinco) dias.",ex:"Os embargos de declaração são a exceção: 5 dias (art. 1.023). Lembre que os prazos contam em dias úteis."}
,{id:"cpp155",m:"pp",ref:"Art. 155, caput, do CPP",t:"O juiz formará sua convicção pela livre apreciação da prova produzida em contraditório judicial, não podendo fundamentar sua decisão exclusivamente nos elementos informativos colhidos na investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas.",l:["exclusivamente", "principalmente", "em nenhuma hipótese", "sequer parcialmente"],e:"O juiz formará sua convicção pela livre apreciação da prova produzida em contraditório judicial, não podendo fundamentar sua decisão principalmente nos elementos informativos colhidos na investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas.",ex:"O inquérito pode reforçar a convicção, mas não sustentar sozinho a condenação. As provas cautelares, não repetíveis e antecipadas são a exceção."}
,{id:"cpp157",m:"pp",ref:"Art. 157, caput, do CPP",t:"São inadmissíveis, devendo ser desentranhadas do processo, as provas ilícitas, assim entendidas as obtidas em violação a normas constitucionais ou legais.",l:["normas constitucionais ou legais", "normas constitucionais, apenas", "normas regimentais dos tribunais", "direitos da vítima"],e:"São inadmissíveis, devendo ser desentranhadas do processo, as provas ilícitas, assim entendidas as obtidas em violação a normas constitucionais, apenas.",ex:"Também são inadmissíveis as provas derivadas das ilícitas, salvo sem nexo causal ou por fonte independente (§1º)."}
,{id:"cpp158",m:"pp",ref:"Art. 158, caput, do CPP",t:"Quando a infração deixar vestígios, será indispensável o exame de corpo de delito, direto ou indireto, não podendo supri-lo a confissão do acusado.",l:["a confissão do acusado", "o depoimento da vítima", "o relatório da autoridade policial", "o laudo de assistente técnico"],e:"Quando a infração deixar vestígios, será indispensável o exame de corpo de delito, direto ou indireto, não podendo supri-lo o depoimento da vítima.",ex:"Se os vestígios desaparecerem, a prova testemunhal pode suprir a falta do exame (art. 167); a confissão, nunca."}
,{id:"cpp283",m:"pp",ref:"Art. 283, caput, do CPP",t:"Ninguém poderá ser preso senão em flagrante delito ou por ordem escrita e fundamentada da autoridade judiciária competente, em decorrência de prisão cautelar ou em virtude de condenação criminal transitada em julgado.",l:["ordem escrita e fundamentada", "ordem verbal ou escrita", "ordem escrita, ainda que sem motivação,", "ordem fundamentada da autoridade policial ou"],e:"Ninguém poderá ser preso senão em flagrante delito ou por ordem verbal ou escrita da autoridade judiciária competente, em decorrência de prisão cautelar ou em virtude de condenação criminal transitada em julgado.",ex:"Repete a garantia do art. 5º, LXI, da Constituição. O STF declarou o artigo constitucional nas ADCs 43, 44 e 54."}
,{id:"cpp306",m:"pp",ref:"Art. 306, §1º, do CPP",t:"Em até 24 (vinte e quatro) horas após a realização da prisão, será encaminhado ao juiz competente o auto de prisão em flagrante e, caso o autuado não informe o nome de seu advogado, cópia integral para a Defensoria Pública.",l:["24 (vinte e quatro) horas", "48 (quarenta e oito) horas", "72 (setenta e duas) horas", "12 (doze) horas"],e:"Em até 48 (quarenta e oito) horas após a realização da prisão, será encaminhado ao juiz competente o auto de prisão em flagrante e, caso o autuado não informe o nome de seu advogado, cópia integral para a Defensoria Pública.",ex:"No mesmo prazo, o preso recebe a nota de culpa (§2º). Também em 24 horas ocorre a audiência de custódia (art. 310)."}
,{id:"cpp313",m:"pp",ref:"Art. 313, I, do CPP",t:"nos crimes dolosos punidos com pena privativa de liberdade máxima superior a 4 (quatro) anos;",l:["máxima superior a 4 (quatro) anos", "mínima superior a 4 (quatro) anos", "máxima igual ou superior a 4 (quatro) anos", "máxima superior a 2 (dois) anos"],e:"nos crimes dolosos punidos com pena privativa de liberdade mínima superior a 4 (quatro) anos;",ex:"Os outros incisos admitem a preventiva em casos como reincidência em crime doloso e violência doméstica para garantir medidas protetivas."}
,{id:"cf37",m:"adm",ref:"Art. 37, caput, da Constituição",t:"A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte:",l:["legalidade, impessoalidade, moralidade, publicidade e eficiência", "legalidade, impessoalidade, moralidade, publicidade e economicidade", "legalidade, isonomia, moralidade, publicidade e eficiência", "legalidade, impessoalidade, motivação, publicidade e eficiência"],e:"A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e economicidade e, também, ao seguinte:",ex:"É o famoso LIMPE. A eficiência foi incluída pela EC 19/1998."}
,{id:"cf37iii",m:"adm",ref:"Art. 37, III, da Constituição",t:"o prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por igual período;",l:["até dois anos, prorrogável uma vez, por igual período", "até dois anos, prorrogável uma vez, por até um ano", "até quatro anos, improrrogável", "até dois anos, prorrogável sucessivas vezes"],e:"o prazo de validade do concurso público será de até dois anos, prorrogável uma vez, por até um ano;",ex:"Quem passa dentro das vagas do edital tem direito à nomeação durante a validade (STF, Tema 161)."}
,{id:"cf37p6",m:"adm",ref:"Art. 37, §6º, da Constituição",t:"As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.",l:["dolo ou culpa", "dolo, apenas", "culpa grave", "qualquer prejuízo"],e:"As pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo, apenas.",ex:"O Estado responde de forma objetiva; o agente, só em regresso e se agiu com dolo ou culpa (STF, Tema 940: a vítima não processa o agente diretamente)."}
,{id:"cf37p4",m:"adm",ref:"Art. 37, §4º, da Constituição",t:"Os atos de improbidade administrativa importarão a suspensão dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.",l:["suspensão dos direitos políticos", "perda dos direitos políticos", "cassação dos direitos políticos", "suspensão dos direitos civis"],e:"Os atos de improbidade administrativa importarão a perda dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma e gradação previstas em lei, sem prejuízo da ação penal cabível.",ex:"A Constituição proíbe a cassação de direitos políticos (art. 15); a improbidade gera suspensão, regulada pela Lei 8.429/1992."}
,{id:"cf41",m:"adm",ref:"Art. 41, caput, da Constituição",t:"São estáveis após três anos de efetivo exercício os servidores nomeados para cargo de provimento efetivo em virtude de concurso público.",l:["três anos", "dois anos", "cinco anos", "um ano"],e:"São estáveis após dois anos de efetivo exercício os servidores nomeados para cargo de provimento efetivo em virtude de concurso público.",ex:"Era de dois anos até a EC 19/1998. Para adquirir estabilidade, também é obrigatória a avaliação especial de desempenho (§4º)."}
,{id:"cf225",m:"amb",ref:"Art. 225, caput, da Constituição",t:"Todos têm direito ao meio ambiente ecologicamente equilibrado, bem de uso comum do povo e essencial à sadia qualidade de vida, impondo-se ao poder público e à coletividade o dever de defendê-lo e preservá-lo para as presentes e futuras gerações.",l:["presentes e futuras gerações", "presentes gerações", "futuras gerações", "gerações atuais e para as espécies ameaçadas"],e:"Todos têm direito ao meio ambiente ecologicamente equilibrado, bem de uso comum do povo e essencial à sadia qualidade de vida, impondo-se ao poder público e à coletividade o dever de defendê-lo e preservá-lo para as presentes gerações.",ex:"É o princípio da solidariedade intergeracional. O dever é do poder público e também da coletividade."}
,{id:"cf225iv",m:"amb",ref:"Art. 225, §1º, IV, da Constituição",t:"exigir, na forma da lei, para instalação de obra ou atividade potencialmente causadora de significativa degradação do meio ambiente, estudo prévio de impacto ambiental, a que se dará publicidade;",l:["significativa degradação", "qualquer degradação", "degradação irreversível", "grave dano comprovado"],e:"exigir, na forma da lei, para instalação de obra ou atividade potencialmente causadora de qualquer degradação do meio ambiente, estudo prévio de impacto ambiental, a que se dará publicidade;",ex:"O EIA é prévio e público. Atividades de menor impacto passam por estudos mais simples no licenciamento."}
,{id:"cf225p3",m:"amb",ref:"Art. 225, §3º, da Constituição",t:"As condutas e atividades consideradas lesivas ao meio ambiente sujeitarão os infratores, pessoas físicas ou jurídicas, a sanções penais e administrativas, independentemente da obrigação de reparar os danos causados.",l:["pessoas físicas ou jurídicas", "pessoas físicas, apenas", "pessoas jurídicas de direito público", "seus administradores, apenas"],e:"As condutas e atividades consideradas lesivas ao meio ambiente sujeitarão os infratores, pessoas físicas, apenas, a sanções penais e administrativas, independentemente da obrigação de reparar os danos causados.",ex:"É a base da responsabilidade penal da pessoa jurídica (Lei 9.605/1998). O STF dispensa a dupla imputação (RE 548.181)."}
,{id:"lca3",m:"amb",ref:"Art. 3º, caput, da Lei 9.605/1998",t:"As pessoas jurídicas serão responsabilizadas administrativa, civil e penalmente conforme o disposto nesta Lei, nos casos em que a infração seja cometida por decisão de seu representante legal ou contratual, ou de seu órgão colegiado, no interesse ou benefício da sua entidade.",l:["no interesse ou benefício da sua entidade", "em qualquer caso, mesmo contra os interesses dela", "no interesse exclusivo do representante", "apenas se houver dano irreversível"],e:"As pessoas jurídicas serão responsabilizadas administrativa, civil e penalmente conforme o disposto nesta Lei, nos casos em que a infração seja cometida por decisão de seu representante legal ou contratual, ou de seu órgão colegiado, em qualquer caso, mesmo contra os interesses dela.",ex:"A responsabilidade da pessoa jurídica não exclui a das pessoas físicas autoras, coautoras ou partícipes (parágrafo único)."}
,{id:"cf201",m:"prev",ref:"Art. 201, caput, da Constituição",t:"A previdência social será organizada sob a forma do Regime Geral de Previdência Social, de caráter contributivo e de filiação obrigatória, observados critérios que preservem o equilíbrio financeiro e atuarial, e atenderá, na forma da lei, a:",l:["caráter contributivo e de filiação obrigatória", "caráter contributivo e de filiação facultativa", "caráter não contributivo e de filiação obrigatória", "caráter solidário e de filiação voluntária"],e:"A previdência social será organizada sob a forma do Regime Geral de Previdência Social, de caráter contributivo e de filiação facultativa, observados critérios que preservem o equilíbrio financeiro e atuarial, e atenderá, na forma da lei, a:",ex:"A assistência social, ao contrário, é prestada a quem dela necessitar, independentemente de contribuição (art. 203)."}
,{id:"pb26",m:"prev",ref:"Art. 26, I, da Lei 8.213/1991",t:"pensão por morte, salário-família e auxílio-acidente;",l:["auxílio-acidente", "salário-maternidade", "aposentadoria por idade", "auxílio-reclusão"],e:"pensão por morte, salário-família e salário-maternidade;",ex:"Esses benefícios independem de carência. O auxílio-reclusão passou a exigir 24 contribuições em 2019 (art. 25, IV)."}
,{id:"cf14p2",m:"eleit",ref:"Art. 14, §2º, da Constituição",t:"Não podem alistar-se como eleitores os estrangeiros e, durante o período do serviço militar obrigatório, os conscritos.",l:["os conscritos", "os militares", "os presos provisórios", "os analfabetos"],e:"Não podem alistar-se como eleitores os estrangeiros e, durante o período do serviço militar obrigatório, os militares.",ex:"Analfabetos podem alistar-se (voto facultativo), mas são inelegíveis (§4º). Portugueses com igualdade de direitos podem alistar-se (art. 12, §1º)."}
,{id:"cf14p4",m:"eleit",ref:"Art. 14, §4º, da Constituição",t:"São inelegíveis os inalistáveis e os analfabetos.",l:["os analfabetos", "os conscritos", "os maiores de setenta anos", "os naturalizados"],e:"São inelegíveis os inalistáveis e os conscritos.",ex:"É a inelegibilidade absoluta, prevista na própria Constituição. As relativas estão nos §§5º a 9º e na LC 64/1990."}
,{id:"cf14p5",m:"eleit",ref:"Art. 14, §5º, da Constituição",t:"O Presidente da República, os Governadores de Estado e do Distrito Federal, os Prefeitos e quem os houver sucedido ou substituído no curso dos mandatos poderão ser reeleitos para um único período subseqüente.",l:["um único período subseqüente", "dois períodos subseqüentes", "quantos períodos o eleitor quiser", "um único período, a qualquer tempo"],e:"O Presidente da República, os Governadores de Estado e do Distrito Federal, os Prefeitos e quem os houver sucedido ou substituído no curso dos mandatos poderão ser reeleitos para dois períodos subseqüentes.",ex:"A regra vale para o Executivo. Para disputar outros cargos, os chefes do Executivo devem renunciar até seis meses antes do pleito (§6º)."}
,{id:"cf16",m:"eleit",ref:"Art. 16 da Constituição",t:"A lei que alterar o processo eleitoral entrará em vigor na data de sua publicação, não se aplicando à eleição que ocorra até um ano da data de sua vigência.",l:["até um ano", "até seis meses", "até dois anos", "até noventa dias"],e:"A lei que alterar o processo eleitoral entrará em vigor na data de sua publicação, não se aplicando à eleição que ocorra até seis meses da data de sua vigência.",ex:"É o princípio da anterioridade eleitoral. Note: a lei entra em vigor logo, mas não se aplica à eleição que ocorra em até um ano."}
,{id:"cf165p3",m:"fin",ref:"Art. 165, §3º, da Constituição",t:"O Poder Executivo publicará, até trinta dias após o encerramento de cada bimestre, relatório resumido da execução orçamentária.",l:["cada bimestre", "cada trimestre", "cada quadrimestre", "cada semestre"],e:"O Poder Executivo publicará, até trinta dias após o encerramento de cada trimestre, relatório resumido da execução orçamentária.",ex:"Não confunda: o relatório resumido da execução orçamentária é bimestral; o relatório de gestão fiscal da LRF é quadrimestral (art. 54)."}
,{id:"lrf19",m:"fin",ref:"Art. 19, caput, da LC 101/2000",t:"Para os fins do disposto no caput do art. 169 da Constituição, a despesa total com pessoal, em cada período de apuração e em cada ente da Federação, não poderá exceder os percentuais da receita corrente líquida, a seguir discriminados:",l:["receita corrente líquida", "receita tributária líquida", "receita total arrecadada", "receita corrente bruta"],e:"Para os fins do disposto no caput do art. 169 da Constituição, a despesa total com pessoal, em cada período de apuração e em cada ente da Federação, não poderá exceder os percentuais da receita tributária líquida, a seguir discriminados:",ex:"Os limites são 50% para a União e 60% para Estados e Municípios."}
,{id:"lrf42",m:"fin",ref:"Art. 42, caput, da LC 101/2000",t:"É vedado ao titular de Poder ou órgão referido no art. 20, nos últimos dois quadrimestres do seu mandato, contrair obrigação de despesa que não possa ser cumprida integralmente dentro dele, ou que tenha parcelas a serem pagas no exercício seguinte sem que haja suficiente disponibilidade de caixa para este efeito.",l:["últimos dois quadrimestres", "últimos dois trimestres", "últimos seis meses", "últimos dois bimestres"],e:"É vedado ao titular de Poder ou órgão referido no art. 20, nos últimos dois trimestres do seu mandato, contrair obrigação de despesa que não possa ser cumprida integralmente dentro dele, ou que tenha parcelas a serem pagas no exercício seguinte sem que haja suficiente disponibilidade de caixa para este efeito.",ex:"Dois quadrimestres são oito meses: a regra evita que o gestor deixe dívidas sem caixa para o sucessor."}
,{id:"eca2",m:"eca",ref:"Art. 2º, caput, do ECA",t:"Considera-se criança, para os efeitos desta Lei, a pessoa até doze anos de idade incompletos, e adolescente aquela entre doze e dezoito anos de idade.",l:["doze anos de idade incompletos", "doze anos de idade completos", "quatorze anos de idade incompletos", "dez anos de idade incompletos"],e:"Considera-se criança, para os efeitos desta Lei, a pessoa até doze anos de idade completos, e adolescente aquela entre doze e dezoito anos de idade.",ex:"Excepcionalmente, o ECA se aplica a pessoas entre 18 e 21 anos (parágrafo único), como na liberação compulsória da internação."}
,{id:"eca39",m:"eca",ref:"Art. 39, §1º, do ECA",t:"A adoção é medida excepcional e irrevogável, à qual se deve recorrer apenas quando esgotados os recursos de manutenção da criança ou adolescente na família natural ou extensa, na forma do parágrafo único do art. 25 desta Lei.",l:["excepcional e irrevogável", "excepcional e revogável", "prioritária e irrevogável", "excepcional e temporária"],e:"A adoção é medida excepcional e revogável, à qual se deve recorrer apenas quando esgotados os recursos de manutenção da criança ou adolescente na família natural ou extensa, na forma do parágrafo único do art. 25 desta Lei.",ex:"Também é vedada a adoção por procuração (§2º)."}
,{id:"eca83",m:"eca",ref:"Art. 83, caput, do ECA",t:"Nenhuma criança ou adolescente menor de 16 (dezesseis) anos poderá viajar para fora da comarca onde reside desacompanhado dos pais ou dos responsáveis sem expressa autorização judicial.",l:["16 (dezesseis) anos", "12 (doze) anos", "14 (quatorze) anos", "18 (dezoito) anos"],e:"Nenhuma criança ou adolescente menor de 12 (doze) anos poderá viajar para fora da comarca onde reside desacompanhado dos pais ou dos responsáveis sem expressa autorização judicial.",ex:"A idade passou de 12 para 16 anos com a Lei 13.812/2019. Há exceções no §1º, como comarca contígua e viagem com parente até o 3º grau."}
,{id:"eca121",m:"eca",ref:"Art. 121, §3º, do ECA",t:"Em nenhuma hipótese o período máximo de internação excederá a três anos.",l:["três anos", "dois anos", "cinco anos", "um ano"],e:"Em nenhuma hipótese o período máximo de internação excederá a dois anos.",ex:"A internação não tem prazo determinado e é reavaliada no máximo a cada seis meses (§2º). A liberação é compulsória aos 21 anos (§5º)."}
,{id:"eca122",m:"eca",ref:"Art. 122, §2º, do ECA",t:"Em nenhuma hipótese será aplicada a internação, havendo outra medida adequada.",l:["outra medida adequada", "vaga em unidade próxima", "pedido da família", "defensor constituído"],e:"Em nenhuma hipótese será aplicada a internação, havendo vaga em unidade próxima.",ex:"A internação segue os princípios da brevidade e da excepcionalidade (art. 121)."}
,{id:"clt840",m:"pt",ref:"Art. 840, caput, da CLT",t:"A reclamação poderá ser escrita ou verbal.",l:["escrita ou verbal", "somente escrita", "escrita ou eletrônica", "verbal, só no rito sumaríssimo"],e:"A reclamação poderá ser somente escrita.",ex:"Se escrita, o pedido deve ser certo, determinado e com indicação de valor (§1º, redação da Reforma Trabalhista)."}
,{id:"clt843p1",m:"pt",ref:"Art. 843, §1º, da CLT",t:"É facultado ao empregador fazer-se substituir pelo gerente, ou qualquer outro preposto que tenha conhecimento do fato, e cujas declarações obrigarão o proponente.",l:["que tenha conhecimento do fato", "que seja empregado da empresa", "com poderes de gerência", "que seja advogado habilitado"],e:"É facultado ao empregador fazer-se substituir pelo gerente, ou qualquer outro preposto que seja empregado da empresa, e cujas declarações obrigarão o proponente.",ex:"Desde a Reforma Trabalhista, o preposto não precisa ser empregado da reclamada (§3º)."}
,{id:"clt844",m:"pt",ref:"Art. 844, caput, da CLT",t:"O não-comparecimento do reclamante à audiência importa o arquivamento da reclamação, e o não-comparecimento do reclamado importa revelia, além de confissão quanto à matéria de fato.",l:["arquivamento da reclamação", "revelia e confissão", "extinção com resolução do mérito", "suspensão do processo"],e:"O não-comparecimento do reclamante à audiência importa o revelia e confissão, e o não-comparecimento do reclamado importa revelia, além de confissão quanto à matéria de fato.",ex:"O reclamante ausente paga custas, mesmo com justiça gratuita, salvo motivo legalmente justificável (§2º)."}
,{id:"clt899",m:"pt",ref:"Art. 899, caput, da CLT",t:"Os recursos serão interpostos por simples petição e terão efeito meramente devolutivo, salvo as exceções previstas neste Título, permitida a execução provisória até a penhora.",l:["efeito meramente devolutivo", "efeito suspensivo", "efeitos devolutivo e suspensivo", "efeito translativo, apenas"],e:"Os recursos serão interpostos por simples petição e terão efeito suspensivo, salvo as exceções previstas neste Título, permitida a execução provisória até a penhora.",ex:"Por isso a execução provisória é permitida até a penhora."}
,{id:"cc966",m:"emp",ref:"Art. 966, caput, do Código Civil",t:"Considera-se empresário quem exerce profissionalmente atividade econômica organizada para a produção ou a circulação de bens ou de serviços.",l:["profissionalmente atividade econômica organizada", "habitualmente atividade econômica lucrativa", "profissionalmente atividade intelectual", "eventualmente atividade econômica organizada"],e:"Considera-se empresário quem exerce habitualmente atividade econômica lucrativa para a produção ou a circulação de bens ou de serviços.",ex:"Quem exerce profissão intelectual, científica, literária ou artística não é empresário, salvo se for elemento de empresa (parágrafo único)."}
,{id:"cc967",m:"emp",ref:"Art. 967 do Código Civil",t:"É obrigatória a inscrição do empresário no Registro Público de Empresas Mercantis da respectiva sede, antes do início de sua atividade.",l:["antes do início de sua atividade", "em até 30 dias do início de sua atividade", "antes do primeiro faturamento", "em até um ano do início de sua atividade"],e:"É obrigatória a inscrição do empresário no Registro Público de Empresas Mercantis da respectiva sede, em até 30 dias do início de sua atividade.",ex:"Sem a inscrição o empresário é irregular, mas continua empresário: a inscrição é declaratória (Enunciado 199 do CJF)."}
,{id:"cc1142",m:"emp",ref:"Art. 1.142, caput, do Código Civil",t:"Considera-se estabelecimento todo complexo de bens organizado, para exercício da empresa, por empresário, ou por sociedade empresária.",l:["todo complexo de bens organizado", "todo imóvel organizado", "todo conjunto de empregados organizado", "todo complexo de bens imóveis"],e:"Considera-se estabelecimento todo imóvel organizado, para exercício da empresa, por empresário, ou por sociedade empresária.",ex:"O estabelecimento não se confunde com o local, que pode ser físico ou virtual (§1º)."}
,{id:"cc1052",m:"emp",ref:"Art. 1.052, caput, do Código Civil",t:"Na sociedade limitada, a responsabilidade de cada sócio é restrita ao valor de suas quotas, mas todos respondem solidariamente pela integralização do capital social.",l:["solidariamente", "subsidiariamente", "proporcionalmente", "individualmente"],e:"Na sociedade limitada, a responsabilidade de cada sócio é restrita ao valor de suas quotas, mas todos respondem subsidiariamente pela integralização do capital social.",ex:"Desde 2019, a limitada pode ter um único sócio (§1º)."}
];
